def patch_test(t):
    add = '''
test("deleting the only row on the last page clamps the next read to the previous page", async () => {
  const user = (await call("/api/users")).data[0];
  const ids = [];
  for (let i = 0; i < 6; i++) {
    const made = await call("/api/threads", "POST", { title: "Clampfixture " + i, body: "Clampfixture body", authorId: user.id, tagNames: ["clamp"] });
    assert.equal(made.status, 201);
    ids.push(made.data.id);
  }
  const query = "/api/threads?q=Clampfixture&tag=clamp&pageSize=5";
  const second = (await call(query + "&page=2")).data;
  assert.equal(second.total, 6);
  assert.equal(second.items.length, 1);
  assert.equal((await call("/api/threads/" + second.items[0].id, "DELETE")).status, 204);
  const again = (await call(query + "&page=2")).data;
  assert.equal(again.total, 5);
  assert.equal(again.page, 1);
  assert.equal(again.items.length, 5);
});
'''
    return t.rstrip('\n') + '\n' + add
assert fe.rw('test/feature.test.ts', patch_test); done.append('review#2 third test: six threads, delete the only row on page 2, re-read page 2 -> clamped to page 1 with five rows and total 5 (the scenario the course narrated is now real)')
def rewrite02(t):
    return fe.replace_section(t, r'State transitions and failure boundaries', """The list route (`server/src/index.ts:34`) runs `SET TRANSACTION ISOLATION LEVEL REPEATABLE READ READ ONLY` before the `COUNT(*)` and the page `SELECT`. What that buys: both statements see the same snapshot, so `total` and `items` can never disagree even if another request inserts a thread between them. What it does not buy: it is not a lock. A concurrent insert is invisible to *this* request and visible to the *next* one; a page fetched a second later may contain a row the first fetch did not know about, which is why "same query twice returns the same ids" in the first test only holds when nothing was inserted in between. The new third test shows the other consequence: deleting the only row on page 2 and re-reading page 2 clamps to page 1, because the clamp is computed from the count inside the same snapshot as the rows.""") or t
fe.rw(fe.chapter(S, '02'), rewrite02); done.append('review#3 02 explains what REPEATABLE READ READ ONLY buys and does not buy')
